using Microsoft.EntityFrameworkCore;

// Cosmos DB provider – EF Core 9 breaking changes applied:
//
// 1. Discriminator property renamed: "$type" is now the default (was "Discriminator").
//    For existing documents that already store "Discriminator", you must explicitly
//    configure the old property name to avoid data mismatches.
//
// 2. Synchronous I/O is no longer supported by the Cosmos DB provider in EF Core 9.
//    All queries/saves must use async methods (ToListAsync, SaveChangesAsync, etc.).

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=stub",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);

            // Breaking change fix: EF Core 9 defaults the discriminator to "$type".
            // Existing documents use "Discriminator" – preserve backward compatibility.
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

// Example query class demonstrating the sync → async migration.
class ProductService
{
    private readonly CosmosDbContext _db;
    public ProductService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 – sync was allowed):
    //   public List<Product> GetAll() => _db.Products.ToList();
    //
    // AFTER (EF Core 9 – sync throws InvalidOperationException):
    public async Task<List<Product>> GetAllAsync()
        => await _db.Products.ToListAsync();

    public async Task AddAsync(Product product)
    {
        _db.Products.Add(product);
        await _db.SaveChangesAsync(); // was _db.SaveChanges() in EF Core 8
    }
}

